-- 564: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 11 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_564_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_564_guard;
INSERT INTO _migration_564_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_041' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'According to the World Health Organization, adolescence covers the age range...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 10 to 19 years","B. 1 to 5 years","C. 5 to 12 years","D. 20 to 29 years"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The WHO defines adolescents as persons aged 10–19 years, the transition from childhood to adulthood. Ages 1–5 are early childhood, 5–12 spans middle childhood with only its tail entering adolescence, and 20–29 is youth or early adulthood. Therefore the correct answer is A: 10 to 19 years.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_041' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_564_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_042' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The period of physical and emotional changes during which a child develops into an adult is called...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Menopause","B. Puberty","C. Infancy","D. Senescence"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Puberty is the stage of rapid growth and sexual maturation — breast development, voice change, menstruation — marking the move into adulthood. Menopause ends reproductive life in middle age, infancy is the first year of life, and senescence is old-age decline. Therefore the correct answer is B: Puberty.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_042' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_564_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_043' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The surest way for an adolescent to avoid sexually transmitted infections and unplanned pregnancy is...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Taking antibiotics regularly","B. Avoiding all social contact with friends","C. Abstinence from premarital sex","D. Using herbal mixtures after intercourse"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Abstinence is the only method that is completely effective against sexually transmitted infections and pregnancy because it removes the risk entirely. Antibiotics do not prevent infection and misuse breeds resistance, avoiding friends is neither necessary nor protective, and unverified herbal mixtures offer no protection at all. Therefore the correct answer is C: Abstinence from premarital sex.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_043' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_564_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_044' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following best describes a balanced diet for a growing adolescent?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Eating only energy-giving foods such as rice and yam","B. Eating large quantities of meat every day","C. Skipping breakfast in order to stay slim","D. Meals containing the right proportions of carbohydrates, proteins, vitamins, minerals, fats and water"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A balanced diet supplies every nutrient class in adequate proportion to fuel growth, learning and immunity. Starch-only meals lack protein and micronutrients, excessive meat unbalances the diet, and skipping meals deprives the growing body of energy and impairs concentration. Therefore the correct answer is D: Meals containing the right proportions of carbohydrates, proteins, vitamins, minerals, fats and water.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_044' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_041', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'According to the World Health Organization, adolescence covers the age range...', 'multiple_choice', NULL, '["A. 10 to 19 years","B. 1 to 5 years","C. 5 to 12 years","D. 20 to 29 years"]', 'A', 'The WHO defines adolescents as persons aged 10–19 years, the transition from childhood to adulthood. Ages 1–5 are early childhood, 5–12 spans middle childhood with only its tail entering adolescence, and 20–29 is youth or early adulthood. Therefore the correct answer is A: 10 to 19 years.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec');
