INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_044', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following best describes a balanced diet for a growing adolescent?', 'multiple_choice', NULL, '["A. Eating only energy-giving foods such as rice and yam","B. Eating large quantities of meat every day","C. Skipping breakfast in order to stay slim","D. Meals containing the right proportions of carbohydrates, proteins, vitamins, minerals, fats and water"]', 'D', 'A balanced diet supplies every nutrient class in adequate proportion to fuel growth, learning and immunity. Starch-only meals lack protein and micronutrients, excessive meat unbalances the diet, and skipping meals deprives the growing body of energy and impairs concentration. Therefore the correct answer is D: Meals containing the right proportions of carbohydrates, proteins, vitamins, minerals, fats and water.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO1', NULL, NULL, 'board_waec');
